import{_ as e,o as d,c as t,a2 as c}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"引导失败排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/boot-failures.md","filePath":"zh/troubleshooting/boot-failures.md"}'),a={name:"zh/troubleshooting/boot-failures.md"};function l(r,o,i,s,n,h){return d(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="引导失败排查" tabindex="-1">引导失败排查 <a class="header-anchor" href="#引导失败排查" aria-label="Permalink to &quot;引导失败排查&quot;">​</a></h1><p>四个程序参与一次引导：<strong>OCBL</strong>（加载器）、<strong>内核</strong> （OCOS）、引导状态契约（<strong>OCST</strong>）与 <strong>OCIRE</strong>（恢复）。 本页按此顺序走遍每类失败，然后是 A/B 槽位逻辑，再是 刻意失败工具（/HANGAT）。</p><h2 id="_1-把引导日志当检查单读" tabindex="-1">1. 把引导日志当检查单读 <a class="header-anchor" href="#_1-把引导日志当检查单读" aria-label="Permalink to &quot;1. 把引导日志当检查单读&quot;">​</a></h2><p>内核按装配顺序为每个子系统打印一行，格式为 <code>[HH:MM:SS.mmm] &lt;stage&gt;: OK|FAIL</code>。安静级别 1 抑制非 FAIL 行；任何含 <code>FAIL</code> 的行对状态判定器都是失败。 OCST 阶梯（也是 OCBL 监视的对象）：<code>BOOT</code>、 <code>KM_AIN_ENTERED</code>、<code>SCHED_READY</code>、<code>DRIVERS_READY</code>、 <code>SERVICES_READY</code>、<code>L1_LAUNCHED</code>、<code>L1_READY</code>，运行时 255 = <code>RUNTIME</code>。</p><p>按位置排查：</p><ol><li><strong>串口上什么都没有</strong> — OCBL 没运行或 ISO 条目 错误。引导 ISO 的另一个条目；试 BIOS 与 UEFI；用 <code>-serial file:boot.log</code> 捕获。</li><li><strong>停在 multiboot2 握手之前</strong> — mb2 交接失败 （<code>[oc] FATAL: bad multiboot2 magic</code> / <code>multiboot2 parse failed</code>） — 捕获串口并检查 mbi 标签解析；你到底有没有经 OCBL/GRUB 引导？</li><li><strong><code>[oc] FATAL: fb_init failed</code></strong> — 没有交接 framebuffer （OCBL 的 <code>[boot] VBE FAILED</code>/<code>GOP FAILED</code> 在它之前）。 修复引导加载器的视频模式。</li><li><strong>停在某个驱动行</strong> — 该家族的探针在你的硬件上 失败；其上的消息指名设备。移除该设备（或 QEMU flag）以确认。</li><li><strong>到达 <code>L0 ready, waiting for L1</code> 但无提示符</strong> — 启动器 失败：<code>l1 launcher: no default L1 app declared</code>（构建损坏）或 <code>failed to start the default L1 app</code>（ush 损坏 — 引导 ISO 并 运行 <code>help_a_test</code>）。</li><li><strong>提示符之后重启</strong> — panic（策略 REBOOT）、watchdog、或 OCBL 判定停滞。第二次启动后：<code>crashlog</code>、<code>dumpinfo</code>、 <code>dmesg</code>、<code>abcfg</code>（引导菜单尝试了什么）、<code>/var/log/crash.log</code>。</li></ol><p>引导自测已经证明：异常路径（计数器 3/3）、 注册表计数（284）、崩溃恢复已武装。如果这些行打印了 OK，平台是健全的 — 看具体特性，别怀疑整台 机器。</p><h2 id="_2-ocbl-的六类扫描器-—-当某个条目缺失" tabindex="-1">2. OCBL 的六类扫描器 — 当某个条目缺失 <a class="header-anchor" href="#_2-ocbl-的六类扫描器-—-当某个条目缺失" aria-label="Permalink to &quot;2. OCBL 的六类扫描器 — 当某个条目缺失&quot;">​</a></h2><p><code>ocbl_scan_all()</code> 枚举驱动器，将 CD 类限制到 2048 字节 扇区，扫过分区，然后回退到整盘 &quot;superfloppy&quot; 检测。每个卷按短路优先级判定：</p><table tabindex="0"><thead><tr><th>优先级</th><th>类</th><th>检测</th><th>菜单标签</th></tr></thead><tbody><tr><td>1</td><td>OCSE</td><td>携带 <code>/ocse.mrk</code> 的 ISO9660 卷（最先判定 — 安装介质绝不会被当作 OCOS 引导，即使上面有内核）</td><td><code>OpenCubeOS Setup (OCSE)</code></td></tr><tr><td>2</td><td>OCOS</td><td>任意带 <code>/boot/opencube.elf</code> 且其前 8 KiB 含 mb2 魔数 <code>0xE85250D6</code> 的卷</td><td><code>Open Cube OS (slot A|B, &lt;size&gt; KiB)</code></td></tr><tr><td>3</td><td>OCIRE</td><td>任意带 <code>/boot/ocire.elf</code> 的卷（含 0xEE 影子与 ISO）</td><td><code>OCIRE recovery</code></td></tr><tr><td>4</td><td>WINDOWS</td><td><code>/EFI/Microsoft/Boot/bootmgfw.efi</code></td><td><code>&lt;volume&gt; ...</code></td></tr><tr><td>5</td><td>LINUX</td><td>带 <code>/EFI/&lt;vendor&gt;/{grubx64,shimx64,systemd-bootx64}.efi</code> 的 ESP</td><td><code>&lt;volume&gt; (hd&lt;N&gt; gpt|p&lt;N&gt;)</code></td></tr><tr><td>6</td><td>GENERIC</td><td><code>/EFI/BOOT/BOOTX64.EFI</code></td><td><code>EFI loader</code></td></tr><tr><td>—</td><td>SHUTDOWN</td><td>合成项，恒为最后</td><td><code>Shutdown</code></td></tr></tbody></table><p>已声明的限制：OCBL 中没有 ext2/3/4 驱动 — Linux/Windows 经其 ESP 检测，绝不经 ext/NTFS 根。</p><p>如果你的卷没出现：</p><ul><li>标记文件缺失/损坏（不带 mb2 魔数的 <code>/boot/opencube.elf</code> 注册为无）。重新安装。</li><li>同时携带 <code>/boot/opencube.elf</code> 与 <code>/boot/ocire.elf</code> 的卷 也会暴露 OCIRE 条目（短路不再隐藏它）。</li><li>A/B 磁盘的分区 2/3 被&quot;槽位占用&quot; — 它们无法 注册自己的条目。</li><li>串口轨迹 <code>[scan] entries: &lt;N&gt;</code> 计数所发现的内容。</li></ul><h2 id="_3-ocbl-自身的失败" tabindex="-1">3. OCBL 自身的失败 <a class="header-anchor" href="#_3-ocbl-自身的失败" aria-label="Permalink to &quot;3. OCBL 自身的失败&quot;">​</a></h2><ul><li><code>[boot] FATAL: payload volume remount failed</code> — 内核加载前的 /boot 重挂载；重新安装。</li><li><code>[boot] FATAL: kernel load failed</code> — ELF 未加载（缺失、 损坏，或段超出 <code>[want_base, 0x40000000)</code>； 防溢出边界即 BUG-46 修复）。</li><li><code>[efi] FATAL: fixed low-memory windows not ...</code> — 0x98000/0x9B000 的 OCST 岛被固件占用；释放低内存或用 BIOS。</li><li><code>[efi] FATAL: memory map failed</code> / <code>ExitBootServices refused</code> — 固件内存服务故障；重试，更新固件。</li><li><code>[chain] VBR read failed</code> / <code>LoadImage failed</code> — chainload 目标不可引导（对非 PE 桩测试盘属预期）。</li><li><code>[boot] ACPI S5 shutdown</code> 然后 <code>[boot] S5 did not power off; halting</code> — 主板忽略 S5。</li></ul><h2 id="_4-引导状态契约-ocst-与判定器" tabindex="-1">4. 引导状态契约（OCST）与判定器 <a class="header-anchor" href="#_4-引导状态契约-ocst-与判定器" aria-label="Permalink to &quot;4. 引导状态契约（OCST）与判定器&quot;">​</a></h2><p>两块固定的低内存块在复位后存活：</p><ul><li><strong>0x98000</strong>（魔数 <code>OCS1</code>）：活动阶段 + 心跳 + kflags — 内核盲写它。</li><li><strong>0x9B000</strong>（魔数 <code>OCB1</code>）：事后记录 <code>{kind, stall, seq, ts_unix, silence_sec, routed, checksum}</code> — kind 为 BOOT_FAILED 或 USER_REQUEST。</li></ul><p>预算：启动 30 s（BOOT→KM_AIN_ENTERED），每阶段 10 s，L1 等待 30 s，运行时心跳 15 s。判定阈值：<strong>RTC 静默 ≥ 8 s</strong> = 引导失败。判定失败时 OCBL 写入 BOOT_FAILED， 显示 <code>Open Cube OS failed to boot at stage: &lt;STAGE&gt;</code>（驻留 4 秒）， 脉冲 8042 复位 — 下次引导<strong>自动路由到 OCIRE， 单次</strong>（<code>ocbl_statemon_route_pending()</code>）。</p><p>如实的非失败（不要追查这些）：<code>previous boot shut down cleanly (seq &lt;n&gt;)</code>、<code>warm reset with recent progress (silence &lt;n&gt;s) - not a failure</code>、<code>previous boot armed no payload - no failure</code>。当 不存在硬件 watchdog 时：<code>BOOT_FAILED record pending ... detection degrades to the next reset</code>。RTC 冻结：<code>[rtc] clock frozen - skipping the dwell</code>（静默不可测 — 检查 RTC 电池）。</p><h2 id="_5-ocire-接管-—-恢复何时发生、它说什么" tabindex="-1">5. OCIRE 接管 — 恢复何时发生、它说什么 <a class="header-anchor" href="#_5-ocire-接管-—-恢复何时发生、它说什么" aria-label="Permalink to &quot;5. OCIRE 接管 — 恢复何时发生、它说什么&quot;">​</a></h2><p>以下情形你会落入 OCIRE：(a) OCBL 判定 BOOT_FAILED（自动路由， 经 <code>routed</code> 位严格单次）；(b) 你选择了 OCIRE 菜单 条目（USER_REQUEST）；(c) 监督器是磁盘默认 （<code>ocire.mode=sup</code>）。</p><p>OCIRE 的第一屏自我解释（<code>ocire_ocbl_report()</code>）：</p><ul><li><code>Recovery session requested by the user (seq &lt;n&gt;)</code> — 你的菜单选择。</li><li><code>Previous boot FAILED at stage &lt;STAGE&gt;</code> + 逐阶段建议： RESET/KM_AIN/SCHED → 运行 <code>syscheck</code>；DRIVERS → <code>syscheck</code> + 复查 驱动；SERVICES → <code>repair</code>；L1_LAUNCHED → <code>syscheck</code>；L1_READY 与 运行时 → <code>logread</code> + <code>repair</code>。</li><li><code>No boot failure was judged - this is a manual recovery session.</code></li></ul><p>然后是恢复阶梯：<code>syscheck</code>（对卷的 10 项检查 — 判定如 <code>BAD (magic/state invalid)</code>、<code>MISSING/UNREADABLE</code>、 <code>DIGEST MISMATCH</code>）、<code>logread</code>（OCBL 引导日志；<code>BAD ring header</code> → <code>repair quick</code>）、<code>repair</code>（从黄金集重建；<code>Type YES</code> 确认会重新格式化系统卷）。监督器级 失败（<code>mailbox write failed - skipping the reboot to avoid a reset loop</code>）意味着重启前必须先修复邮箱 — 该防护 是 BUG-47 修复。</p><h2 id="_6-a-b-槽位与回滚" tabindex="-1">6. A/B 槽位与回滚 <a class="header-anchor" href="#_6-a-b-槽位与回滚" aria-label="Permalink to &quot;6. A/B 槽位与回滚&quot;">​</a></h2><p>磁盘上的 A/B 布局：p1 引导/标志（FAT32，32 MB：<code>/boot/next_B</code>、 <code>/boot/ok_B</code>、<code>/boot/bootfail_B</code>、grub.cfg），p2 槽 A（128 MB），p3 槽 B（128 MB），p4 /data。<code>judge_volume()</code> 中的槽位选择：</p><ul><li><code>next_B</code> 存在且 <code>bootfail_B</code> 缺失 → 引导 <strong>B</strong>（分区 3）。</li><li><code>next_B</code> + <code>bootfail_B</code> 同时存在 → <strong>回滚到 A</strong>（分区 2），菜单 标签追加 <code> rollback</code> — 这就是自动回滚触发器： B 内核在引导时悲观地写入 <code>bootfail_B</code>，仅在系统完全 起来后才删除它。</li><li><code>ok_B</code> 存在 → B；否则 → A。</li><li>当前槽位经 mb2 cmdline <code>oc.slot=A|B|ISO</code> 到达； 引导尝试预算存于 <code>/boot/grub/grubenv</code>（<code>ab_attempts</code>， 上限 3；A 完成引导或 B 确认时内核重置它）。</li></ul><p>命令：<code>update status</code>（槽位 + 版本 + <code>A/B disk: present</code> 锚点）、<code>abcfg</code>（引导配置）、<code>rollback</code>（清除标志）、 <code>ab_partition_test</code>（协议测试）。过期标志令菜单选错 槽位：从 OCBL 菜单强制另一槽位，然后从运行中的系统 执行 <code>update rollback</code>。</p><h2 id="_7-hangat-—-刻意停滞与排除法" tabindex="-1">7. /HANGAT — 刻意停滞与排除法 <a class="header-anchor" href="#_7-hangat-—-刻意停滞与排除法" aria-label="Permalink to &quot;7. /HANGAT — 刻意停滞与排除法&quot;">​</a></h2><p><code>/HANGAT</code> 是载荷卷上的一个 1 字节诊断文件（&#39;1&#39;..&#39;7&#39;）； OCBL 静默地向内核 cmdline 追加 <code>oc.hang=N</code>， 随系统发布的内核刻意在阶段 N 后停机（&#39;7&#39; = L1_READY 之后的 运行时挂起）。目的：从发布镜像演练完整的 watchdog→复位→OCBL 判定→OCIRE 路由链，<strong>无需测试构建的 内核</strong>。</p><p>存在时的症状（而你并非有意为之）：内核在某个 阶段关中断停机；串口显示 <code>[ocst] /HANGAT diagnostic: will halt after stage &lt;N&gt;</code> 与 <code>[ocst] HANGAT: deliberate halt with interrupts off </code>；OCBL 显示 <code> (the kernel will halt after the stage)</code>。</p><p><strong>排除法</strong>：如果引导在硬件干净的前提下持续&quot;失败&quot;于同一 阶段，先检查载荷卷上的 <code>/HANGAT</code> — 从 OCIRE 或另一台 机器挂载该卷并删除它。没有该文件时完全无操作。</p><h2 id="_8-ocse-引导失败-安装介质" tabindex="-1">8. OCSE 引导失败（安装介质） <a class="header-anchor" href="#_8-ocse-引导失败-安装介质" aria-label="Permalink to &quot;8. OCSE 引导失败（安装介质）&quot;">​</a></h2><ul><li><code>[ocse] FATAL: no usable disk - halting</code> — 接入一块目标磁盘。</li><li><code>ocblmbr.bin MISSING</code> / <code>ocos.tar MISSING</code> — 安装介质 不完整：重新下载 ISO，核对大小/SHA（BUG-107 是 历史上的不匹配）。</li><li><code>[ocse] STAGE &lt;n&gt; FAILED: &lt;what&gt;</code> — 安装器内核自身的 装配；镜像的 OCOS 消息适用。</li><li>安装器步骤链及其修复： <a href="./error-catalog.html">error-catalog.md</a> §3.4。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./error-codes.html">error-codes.md</a> — panic 位点、阶段格式</li><li><a href="./error-catalog.html">error-catalog.md</a> §1-§4 — 每条引导侧消息</li><li><a href="./../manual/boot-modes.html">../manual/boot-modes.md</a> — 八种引导 模式</li><li><a href="./../manual/recovery.html">../manual/recovery.md</a> — OCIRE 用法</li><li><a href="./qemu-debugging.html">qemu-debugging.md</a> — 捕获、三重故障 调试</li></ul>',37)])])}const b=e(a,[["render",l]]);export{g as __pageData,b as default};
